-- Reference lists for the employee profile fields, seeded from the
-- "Database Fields" workbook. Each is a table rather than a CHECK list so
-- the options can be maintained without a migration.

create table if not exists qualification_degrees (
  id       smallint generated always as identity primary key,
  name_en  text not null unique,
  name_ar  text not null,
  sort_order smallint not null default 0
);

create table if not exists bus_routes (
  id       smallint generated always as identity primary key,
  name     text not null unique,
  sort_order smallint not null default 0,
  is_active boolean not null default true
);

-- Keyed by the real governorate code carried inside the national ID, so a
-- lookup from an ID is a primary key hit.
create table if not exists governorates (
  code     smallint primary key,
  name_ar  text not null
);

