-- The official social insurance job-title list, 5,500-odd entries,
-- seeded from the "S.I. Codes" sheet of the workbook. It is a table so the
-- Database page can offer a searchable picker and so a stored code can be
-- resolved to its Arabic title by a join rather than a lookup the client
-- has to carry.

create table if not exists si_codes (
  code   text primary key,
  title  text not null
);

create index if not exists si_codes_title_idx on si_codes (title text_pattern_ops);

