-- ---------------------------------------------------------------------
-- These are reference lists, like sites and departments: everyone signed
-- in may read them, only a super admin may change them.
-- ---------------------------------------------------------------------

alter table qualification_degrees enable row level security;
alter table bus_routes            enable row level security;
alter table governorates          enable row level security;
alter table si_codes              enable row level security;

do $$
declare t text;
begin
  foreach t in array array['qualification_degrees','bus_routes','governorates','si_codes'] loop
    execute format('drop policy if exists %I_read on %I', t, t);
    execute format('drop policy if exists %I_write on %I', t, t);
    execute format($p$create policy %I_read on %I for select to authenticated
                      using (my_role() <> 'no_access'::app_role)$p$, t, t);
    execute format($p$create policy %I_write on %I for all to authenticated
                      using (is_super_admin()) with check (is_super_admin())$p$, t, t);
    execute format('grant select on %I to authenticated', t);
  end loop;
end $$;
